<?php namespace App\Controllers;
use App\Models\SaleModel; use App\Models\ProductModel; use App\Models\CustomerModel;
class Sales extends BaseController
{
 public function index(){ $db=db_connect(); $sales=$db->table('sales s')->select('s.*,p.name product_name,c.full_name customer_name,u.full_name staff_name')->join('products p','p.id=s.product_id')->join('customers c','c.id=s.customer_id','left')->join('users u','u.id=s.sold_by')->orderBy('s.id','DESC')->get()->getResultArray(); return $this->render('sales/index',['title'=>'Sales history','sales'=>$sales]); }
 public function create(){ $pm=new ProductModel(); if($this->request->getMethod()==='post'){ if(!$this->validate(['product_id'=>'required|integer','customer_id'=>'permit_empty|integer','quantity'=>'required|integer|greater_than[0]'])) return redirect()->back()->withInput()->with('errors',$this->validator->getErrors()); $product=$pm->find((int)$this->request->getPost('product_id'));$qty=(int)$this->request->getPost('quantity'); if(!$product)return redirect()->back()->withInput()->with('error','Product not found.'); if($qty>$product['stock_quantity'])return redirect()->back()->withInput()->with('error','Not enough stock. Available: '.$product['stock_quantity'].'.'); $db=db_connect();$db->transStart();$pm->update($product['id'],['stock_quantity'=>$product['stock_quantity']-$qty]);(new SaleModel())->insert(['product_id'=>$product['id'],'customer_id'=>$this->request->getPost('customer_id')?:null,'sold_by'=>session('user_id'),'quantity'=>$qty,'total_price'=>$qty*(float)$product['price'],'created_at'=>date('Y-m-d H:i:s')]);$db->transComplete();return redirect()->to('/sales')->with('success','Sale recorded and inventory updated.'); } return $this->render('sales/form',['title'=>'Record sale','products'=>$pm->where('stock_quantity >',0)->orderBy('name')->findAll(),'customers'=>(new CustomerModel())->orderBy('full_name')->findAll()]); }
}
